                    class="inline-flex items-center gap-1 px-2 py-1 rounded-lg bg-blue-50 text-blue-700 hover:bg-blue-100 text-xs font-semibold cursor-pointer"
                  >
                    <i data-lucide="image" class="w-3.5 h-3.5"></i>
