// ============================================================================
let livePollingTimer = null;

function getComputedSepayBalance() {
  const stg = appState.settings || {};
  const transactions = appState.transactions || [];
  const totalIn = transactions.filter(t => t.type === 'Thu').reduce((s, t) => s + (Number(t.amount) || 0), 0);
  const totalOut = transactions.filter(t => t.type === 'Chi').reduce((s, t) => s + (Number(t.amount) || 0), 0);
  const netBalance = totalIn - totalOut;

  if (stg.sepayBalance !== undefined && stg.sepayBalance !== '' && !isNaN(Number(stg.sepayBalance))) {
    const savedBal = Number(stg.sepayBalance);
    // Nếu sepayBalance đang là 0 mặc định nhưng hệ thống đã có phiếu thu học phí thực tế, hiển thị tổng thực thu
    if (savedBal === 0 && netBalance !== 0) {
      return netBalance;
    }
    return savedBal;
  }
  return netBalance;
}

function renderSepayBalanceBanner() {
  const stg = appState.settings || {};
  const bankBadge = document.getElementById('sepay-bank-badge');
  const balanceEl = document.getElementById('sepay-live-balance');
  const alertTimeEl = document.getElementById('sepay-last-alert-time');
  const alertTextEl = document.getElementById('sepay-last-alert-text');

  if (bankBadge) {
    bankBadge.textContent = `${stg.bankBin || 'BIDV'} • ${stg.bankAccountNo || '8601774789'}`;
  }
  if (balanceEl) {
    balanceEl.textContent = formatCurrency(getComputedSepayBalance());
  }

  if (alertTextEl && alertTimeEl) {
    if (stg.lastBankAlertJson) {
      try {
        const alertObj = JSON.parse(stg.lastBankAlertJson);
        const isOut = alertObj.type === 'out';
        const sign = isOut ? '-' : '+';
        alertTimeEl.textContent = alertObj.time || 'Vừa xong';
        alertTextEl.className = `text-xs sm:text-sm font-bold mt-0.5 truncate ${
          isOut ? 'text-rose-300' : 'text-emerald-300'
        }`;
        alertTextEl.textContent = `${sign}${formatCurrency(alertObj.amount || 0)} | ND: ${
          alertObj.content || 'Giao dịch ngân hàng'
        }`;
      } catch (e) {
        alertTimeEl.textContent = 'Đang kết nối';
        alertTextEl.textContent = 'Đang chờ thông báo biến động số dư từ SePay.vn...';
      }
    } else {
      alertTimeEl.textContent = 'Sẵn sàng';
      alertTextEl.textContent = 'Đang chờ thông báo biến động số dư từ SePay.vn (Hoặc bấm "Test Báo Số Dư")...';
    }
  }
}

async function promptEditSepayBalance() {
  const currentBal = getComputedSepayBalance();
  const input = prompt(
    'Nhập số dư thực tế hiện tại trong tài khoản BIDV (8601774789) của bạn (VNĐ):\n(Khi có giao dịch mới từ SePay, số dư sẽ tự động cập nhật theo ngân hàng)',
    String(currentBal)
  );
  if (input === null) return;
  const cleaned = Number(String(input).replace(/[^0-9-]/g, ''));
  if (isNaN(cleaned)) {
    showToast('Số tiền không hợp lệ!', 'error');
    return;
  }
  if (!appState.settings) appState.settings = {};
  appState.settings.sepayBalance = String(cleaned);
  saveStateToLocal();
  await triggerAutoSyncIfNeeded(`Đã cập nhật số dư ngân hàng hiện tại: ${formatCurrency(cleaned)}!`);
}

