function playTingSound() {
  const soundToggle = document.getElementById('sepay-sound-toggle');
  if (soundToggle && !soundToggle.checked) return;
  try {
    const AudioCtx = window.AudioContext || window.webkitAudioContext;
    if (!AudioCtx) return;
    const ctx = new AudioCtx();
    // Nốt 1 (Ting)
    const osc1 = ctx.createOscillator();
    const gain1 = ctx.createGain();
    osc1.type = 'sine';
    osc1.frequency.setValueAtTime(880, ctx.currentTime); // A5
    gain1.gain.setValueAtTime(0.25, ctx.currentTime);
    gain1.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.35);
    osc1.connect(gain1);
    gain1.connect(ctx.destination);
    osc1.start(ctx.currentTime);
    osc1.stop(ctx.currentTime + 0.35);

    // Nốt 2 (Ting cao hơn)
    const osc2 = ctx.createOscillator();
    const gain2 = ctx.createGain();
    osc2.type = 'sine';
    osc2.frequency.setValueAtTime(1318.5, ctx.currentTime + 0.16); // E6
    gain2.gain.setValueAtTime(0.3, ctx.currentTime + 0.16);
    gain2.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.75);
    osc2.connect(gain2);
    gain2.connect(ctx.destination);
    osc2.start(ctx.currentTime + 0.16);
    osc2.stop(ctx.currentTime + 0.75);
  } catch (e) {
    // Trình duyệt chặn autoplay âm thanh nếu chưa tương tác
  }
}

function startLiveBankPolling() {
  if (livePollingTimer) clearInterval(livePollingTimer);
  const checkbox = document.getElementById('setting-live-polling');
  const isEnabled = checkbox ? checkbox.checked : true;
  if (!isEnabled) return;

  const webhookDisplay = document.getElementById('bank-webhook-url-display');
  if (webhookDisplay && getGasUrl()) {
    webhookDisplay.textContent = getGasUrl();
  }

  livePollingTimer = setInterval(async () => {
    const gasUrl = getGasUrl();
    if (!gasUrl) return;
    try {
      const prevPaidSet = new Set(
        (appState.students || [])
          .filter(s => s.status === 'Đã hoàn thành')
          .map(s => s.studentCode + '_' + s.period)
      );
      const prevAlertJson = appState.settings?.lastBankAlertJson || '';

      const res = await fetch(`${gasUrl}?action=getAll&t=${Date.now()}`, {
        method: 'GET',
        redirect: 'follow'
      });
      const json = await res.json();
      if (json && json.success && json.data) {
        const nextState = mergeServerData(json.data);
        const newlyPaid = (nextState.students || []).filter(
          s => s.status === 'Đã hoàn thành' && !prevPaidSet.has(s.studentCode + '_' + s.period)
        );
        const nextAlertJson = nextState.settings?.lastBankAlertJson || '';
        const hasNewBankAlert = nextAlertJson && nextAlertJson !== prevAlertJson;

        if (newlyPaid.length > 0 || hasNewBankAlert) {
          appState = nextState;
          saveStateToLocal();
          playTingSound();

          if (hasNewBankAlert) {
            try {
              const alertObj = JSON.parse(nextAlertJson);
              const sign = alertObj.type === 'out' ? '-' : '+';
              showToast(
                `💰 SEPAY BÁO SỐ DƯ: ${sign}${formatCurrency(alertObj.amount)} | Số dư mới: ${formatCurrency(
                  alertObj.balance ?? getComputedSepayBalance()
                )} | ND: ${alertObj.content}`,
                'success'
              );
            } catch (e) {}
          }

          newlyPaid.forEach(st => {
            showToast(
              `🔔 ĐÃ DUYỆT TỰ ĐỘNG: Học sinh ${st.fullName} (${st.studentCode}) vừa hoàn thành học phí (${formatCurrency(
                st.tuitionFee
              )})!`,
              'success'
            );
          });
        }
      }
    } catch (e) {
      // Bỏ qua lỗi mạng tạm thời khi polling ngầm
    }
  }, 12000);
}

function toggleLiveBankPolling(enabled) {
  if (enabled) {
    startLiveBankPolling();
    showToast('Đã bật tự động kiểm tra thông báo số dư SePay (12 giây/lần)!', 'success');
  } else {
    if (livePollingTimer) clearInterval(livePollingTimer);
    livePollingTimer = null;
    showToast('Đã tạm dừng tự động kiểm tra giao dịch ngầm.', 'info');
  }
}

async function quickTestSepayAlert() {
  // Tìm 1 học sinh đang Chưa đóng hoặc lấy học sinh đầu tiên để test báo số dư + tự động gạch nợ
  const targetStu =
    (appState.students || []).find(s => s.status !== 'Đã hoàn thành') ||
    (appState.students || [])[0];

  const simContentEl = document.getElementById('sim-bank-content');
  const simAmountEl = document.getElementById('sim-bank-amount');

  if (targetStu) {
    const cleanName = removeVietnameseTones(targetStu.fullName).toUpperCase();
    if (simContentEl) simContentEl.value = `HP ${targetStu.studentCode} ${cleanName}`;
    if (simAmountEl) simAmountEl.value = targetStu.tuitionFee || 600000;
  } else {
    if (simContentEl && !simContentEl.value) simContentEl.value = 'CHUYEN KHOAN HOC PHI TEST SEPAY';
    if (simAmountEl && !simAmountEl.value) simAmountEl.value = 600000;
  }

  await simulateIncomingBankTransfer();
}

function findStudentFromTransferContent(rawContent) {
  const cleanContent = removeVietnameseTones(rawContent || '')
    .toUpperCase()
    .replace(/[^A-Z0-9 ]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
  if (!cleanContent) return null;

  const students = appState.students || [];

  // Vòng 1: Khớp theo Mã HS, Họ tên đầy đủ hoặc SĐT phụ huynh
  for (const s of students) {
    const code = removeVietnameseTones(s.studentCode || '').toUpperCase().trim();
    const name = removeVietnameseTones(s.fullName || '').toUpperCase().replace(/\s+/g, ' ').trim();
    const phone = String(s.parentPhone || '').replace(/[^0-9]/g, '');

    if (
      (code && code.length >= 3 && cleanContent.includes(code)) ||
      (name && name.length >= 5 && cleanContent.includes(name)) ||
      (phone && phone.length >= 8 && cleanContent.includes(phone))
    ) {
      return s;
    }
  }

  // Vòng 2: Khớp theo 2 từ cuối của tên học sinh (VD: MINH ANH, GIA HUY, BAO NGOC)
  for (const s of students) {
    const name = removeVietnameseTones(s.fullName || '').toUpperCase().replace(/\s+/g, ' ').trim();
    const words = name.split(' ').filter(Boolean);
    if (words.length >= 2) {
      const shortName = words.slice(-2).join(' ');
      if (shortName.length >= 5 && cleanContent.includes(shortName)) {
        return s;
      }
    }
  }

  return null;
}

async function simulateIncomingBankTransfer() {
  const contentInput = document.getElementById('sim-bank-content');
  const amountInput = document.getElementById('sim-bank-amount');
  const rawContent = (contentInput?.value || 'HP HS001 NGUYEN MINH ANH').trim();
  const amount = Number(amountInput?.value) || 600000;

  if (!rawContent) {
    showToast('Vui lòng nhập nội dung chuyển khoản giả lập (VD: HP HS001 NGUYEN MINH ANH)!', 'warning');
    return;
  }

  const nowStr = getCurrentDateTimeString();
  const todayDate = new Date().toISOString().slice(0, 10);

  // Tìm học sinh khớp Mã HS, Họ tên đầy đủ, Tên gọi hoặc SĐT trong nội dung chuyển khoản
  const matchedStudent = findStudentFromTransferContent(rawContent);

  const finalAmount = amount > 0 ? amount : matchedStudent ? matchedStudent.tuitionFee : 600000;
  const prevBalance = getComputedSepayBalance();
  const newBalance = prevBalance + finalAmount;
  const txRefId = 'SEPAY_STK_' + Date.now();

  if (!appState.settings) appState.settings = {};
  appState.settings.sepayBalance = String(newBalance);
  appState.settings.lastBankAlertJson = JSON.stringify({
    id: txRefId,
    time: nowStr,
    type: 'in',
    amount: finalAmount,
    balance: newBalance,
    content: rawContent,
    gateway: appState.settings.bankBin || 'BIDV',
    accountNumber: appState.settings.bankAccountNo || '8601774789'
  });

  if (matchedStudent) {
    matchedStudent.status = 'Đã hoàn thành';
    matchedStudent.updatedAt = nowStr;
    matchedStudent.note = `Đã CK vào STK: +${formatCurrency(finalAmount)} (${nowStr})`;

    // 1. Tự động lưu / cập nhật vào danh sách Xác nhận chuyển khoản
    if (!appState.paymentRequests) appState.paymentRequests = [];
    let updatedExistingReq = false;
    appState.paymentRequests.forEach(r => {
      if (r.studentCode === matchedStudent.studentCode && r.status === 'Chờ duyệt') {
        r.status = 'Đã duyệt';
        r.reviewedAt = nowStr;
        updatedExistingReq = true;
      }
    });
    if (!updatedExistingReq) {
      appState.paymentRequests.unshift({
        id: 'YC_' + txRefId,
        submittedAt: nowStr,
        studentRecordId: matchedStudent.id,
        studentCode: matchedStudent.studentCode,
        studentName: matchedStudent.fullName,
        className: matchedStudent.className,
        period: matchedStudent.period,
        amount: finalAmount,
        parentPhone: matchedStudent.parentPhone || '',
        payerName: 'Chuyển khoản STK tự động',
        note: `Tự động lưu từ STK (${appState.settings.bankAccountNo || '8601774789'}) | ND: ${rawContent}`,
        receiptUrl: '',
        status: 'Đã duyệt',
        reviewedAt: nowStr
      });
    }
  }

  // 2. Tự động lưu Phiếu Thu vào Sổ Thu - Chi (tránh tạo trùng phiếu thu nếu học sinh đã có phiếu thu kỳ này)
  if (!appState.transactions) appState.transactions = [];
  const alreadyHasStudentPeriodTx =
    matchedStudent &&
    appState.transactions.some(
      t =>
        t.type === 'Thu' &&
        t.studentCode === matchedStudent.studentCode &&
        t.description &&
        t.description.includes(matchedStudent.period)
    );

  if (!alreadyHasStudentPeriodTx) {
    appState.transactions.unshift({
      id: 'GD_' + txRefId,
      date: todayDate,
      type: 'Thu',
      category: 'Thu học phí',
      amount: finalAmount,
      description: matchedStudent
        ? `Tự động lưu CK vào STK: ${matchedStudent.studentCode} - ${matchedStudent.fullName} (${matchedStudent.period}) | ND: ${rawContent}`
        : `Tự động lưu CK vào STK (${appState.settings.bankAccountNo || '8601774789'}): +${formatCurrency(finalAmount)} | ND: ${rawContent}`,
      studentCode: matchedStudent ? matchedStudent.studentCode : '',
      method: 'Chuyển khoản STK (Tự động)',
      receiptUrl: '',
      createdBy: 'Tự động từ STK (SePay)'
    });
  }

  playTingSound();
  saveStateToLocal();

  const msg = matchedStudent
    ? `💰 ĐÃ NHẬN CK VÀO STK (+${formatCurrency(finalAmount)}) -> Tự động lưu thông tin & cộng số đợt đã đóng cho ${matchedStudent.fullName}!`
    : `💰 ĐÃ NHẬN CK VÀO STK (+${formatCurrency(finalAmount)}) | Số dư mới: ${formatCurrency(
        newBalance
      )} -> Đã tự động lưu vào Sổ Thu - Chi!`;

  await triggerAutoSyncIfNeeded(msg);
}


